with (out/'RESTORATION_MATRIX.csv').open('w',newline='',encoding='utf-8-sig')as f:
 w=csv.writer(f);w.writerow(['ID','분류','대상','원본 주소','바이너리 확인','현재 구현','차이','다음 처리','현재 소스'])
 for r in rows:w.writerow([r['id'],r['status_ko'],r['name'],','.join(r['original']),r['binary_facts'],r['current_facts'],r['difference'],r['next_action'],'; '.join(v['path']+':'+str(v['line'])for v in r['current_sources'])])
lines=[]
for r in rows:
 orig=', '.join('`'+v+'`'for v in r['original'])or'범위 구분'
 refs=' · '.join('['+Path(v['path']).name+':'+str(v['line'])+']('+v['url']+')'for v in r['current_sources'])
 proof=' · '.join('[근거'+str(i+1)+']('+v+')'for i,v in enumerate(r['evidence']))
 lines.append('| '+r['id']+' | '+r['status_ko']+' | '+r['name']+' | '+orig+' | '+r['difference']+' | '+'['+Path(r['current_sources'][0]['path']).name+':'+str(r['current_sources'][0]['line'])+']('+r['current_sources'][0]['url']+') · [명령]('+r['evidence'][0]+')'+' |')
(root/'NETWORK_AUDIT_MATRIX_TABLE.md').write_text('| ID | 판정 | 대상 | 원본 주소 | 현재 구현과 차이 | 소스·명령 근거 |\n|---|---|---|---|---|---|\n'+'\n'.join(lines)+'\n')
